func TestEnumWhoamiDtoKind(t *testing.T) {
	t.Run("NewFromString_first_party", func(t *testing.T) {
		t.Parallel()
		val, err := NewWhoamiDtoKindFromString("first-party")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WhoamiDtoKind("first-party"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_delegated", func(t *testing.T) {
		t.Parallel()
		val, err := NewWhoamiDtoKindFromString("delegated")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WhoamiDtoKind("delegated"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_api_token", func(t *testing.T) {
		t.Parallel()
		val, err := NewWhoamiDtoKindFromString("api-token")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WhoamiDtoKind("api-token"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_legacy_api_key", func(t *testing.T) {
		t.Parallel()
		val, err := NewWhoamiDtoKindFromString("legacy-api-key")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WhoamiDtoKind("legacy-api-key"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewWhoamiDtoKindFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewWhoamiDtoKindFromString("first-party")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

func TestExtraPropertiesAccountUserSummaryDto(t *testing.T) {
	t.Run("GetExtraProperties", func(t *testing.T) {
		t.Parallel()
		obj := &AccountUserSummaryDto{}
		// Should not panic when calling GetExtraProperties()
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("GetExtraProperties() panicked: %v", r)
			}
		}()
		extraProps := obj.GetExtraProperties()
		// Result can be nil or an empty/non-empty map
		_ = extraProps
	})

	t.Run("GetExtraProperties_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *AccountUserSummaryDto
		extraProps := obj.GetExtraProperties()
		assert.Nil(t, extraProps, "nil receiver should return nil without panicking")
	})
}

